// Forwarder intercepts kubernetes requests, acting as Kubernetes API proxy.
// it blindly forwards most of the requests on HTTPS protocol layer,
// however some requests like exec sessions it intercepts and records.
type Forwarder struct {
	sync.Mutex
	ForwarderConfig
	router *httprouter.Router

	// log specifies the logger
	log log.FieldLogger
	// userCredentials caches only short lived credentials for authenticated
	// users. Cluster sessions contain request and connection state and are
	// created separately for every request.
	userCredentials *ttlmap.TTLMap
	// activeRequests is a map used to serialize active CSR requests to the auth server
	activeRequests map[string]context.Context
	// close is a close function
	close context.CancelFunc
	// ctx is a global context signalling exit
	ctx context.Context
	// creds contain kubernetes credentials for multiple clusters.
	// map key is cluster name.
	creds map[string]*kubeCreds
}

// ServeHTTP delegates Kubernetes requests to the forwarder's router.
func (f *Forwarder) ServeHTTP(rw http.ResponseWriter, r *http.Request) {
	f.router.ServeHTTP(rw, r)
}

// Close signals close to all outstanding or background operations
// to complete
func (f *Forwarder) Close() error {
	f.close()
	return nil
}

// authContext is a context of authenticated user,
// contains information about user, target cluster and authenticated groups
type authContext struct {
	auth.Context
	kubeGroups      map[string]struct{}
	kubeUsers       map[string]struct{}
	kubeCluster     string
	teleportCluster teleportClusterClient
	clusterConfig   services.ClusterConfig
	// clientIdleTimeout sets information on client idle timeout
	clientIdleTimeout time.Duration
	// disconnectExpiredCert if set, controls the time when the connection
	// should be disconnected because the client cert expires
	disconnectExpiredCert time.Time
	// clientCertExpires is part of the credential cache key even when the
	// cluster does not disconnect connections on certificate expiration.

	parent    *Forwarder
	creds     *kubeCreds
	tlsConfig *tls.Config
	forwarder *forward.Forwarder
	// noAuditEvents is true if this teleport service should leave audit event
	// logging to another service.
	noAuditEvents bool
}

func (s *clusterSession) monitorConn(conn net.Conn, err error) (net.Conn, error) {
	if err != nil {
		return nil, trace.Wrap(err)
	}
	if s.disconnectExpiredCert.IsZero() && s.clientIdleTimeout == 0 {
		return conn, nil
	}
	ctx, cancel := context.WithCancel(s.parent.ctx)
	tc := &trackingConn{
		Conn:   conn,
		clock:  s.parent.Clock,
		ctx:    ctx,
		cancel: cancel,
	}

	mon, err := srv.NewMonitor(srv.MonitorConfig{
		DisconnectExpiredCert: s.disconnectExpiredCert,
		ClientIdleTimeout:     s.clientIdleTimeout,
		Clock:                 s.parent.Clock,
		Tracker:               tc,
		Conn:                  tc,
		Context:               ctx,
		TeleportUser:          s.User.GetName(),
		ServerID:              s.parent.ServerID,
		Entry:                 s.parent.log,
		Emitter:               s.parent.AuthClient,
	})
	if err != nil {
		tc.Close()
		return nil, trace.Wrap(err)
	}
	go mon.Start()
	return tc, nil
}

func (s *clusterSession) Dial(network, addr string) (net.Conn, error) {
	return s.monitorConn(s.teleportCluster.Dial(network, addr))
}

func (s *clusterSession) DialWithContext(ctx context.Context, network, addr string) (net.Conn, error) {
	return s.monitorConn(s.teleportCluster.DialWithContext(ctx, network, addr))
}

type trackingConn struct {
	sync.RWMutex
	net.Conn
	clock      clockwork.Clock
	lastActive time.Time
	ctx        context.Context
	cancel     context.CancelFunc
}

// Read reads data from the connection.
// Read can be made to time out and return an Error with Timeout() == true
// after a fixed time limit; see SetDeadline and SetReadDeadline.
func (t *trackingConn) Read(b []byte) (int, error) {
	n, err := t.Conn.Read(b)
	t.UpdateClientActivity()
	return n, err
}

func (t *trackingConn) Close() error {
	t.cancel()
	return t.Conn.Close()
}

// GetClientLastActive returns time when client was last active
func (t *trackingConn) GetClientLastActive() time.Time {
	t.RLock()
	defer t.RUnlock()
	return t.lastActive
}

// UpdateClientActivity sets last recorded client activity
func (t *trackingConn) UpdateClientActivity() {
	t.Lock()
	defer t.Unlock()
	t.lastActive = t.clock.Now().UTC()
}

func (f *Forwarder) getOrCreateClusterSession(ctx authContext) (*clusterSession, error) {
	return f.newClusterSession(ctx)
}

type userCredentials struct {
	tlsConfig *tls.Config
	notAfter  time.Time
}

func (f *Forwarder) now() time.Time {
	if f.Clock != nil {
		return f.Clock.Now()
	}
	return time.Now()
}

func (f *Forwarder) getUserCredentials(ctx authContext) *tls.Config {
	f.Lock()
	defer f.Unlock()
	if f.userCredentials == nil {
		return nil
	}
	value, ok := f.userCredentials.Get(ctx.key())
	if !ok {
		return nil
	}
	creds := value.(*userCredentials)
	if f.now().Add(time.Minute).After(creds.notAfter) {
		f.userCredentials.Remove(ctx.key())
		return nil
	}
	return creds.tlsConfig
}

// getOrRequestCertificate shares only the user certificate across requests.
// Each request still gets its own cluster session, dialer and forwarding state.
func (f *Forwarder) getOrRequestCertificate(ctx authContext) (*tls.Config, error) {
	forwarderCtx := f.ctx
	if forwarderCtx == nil {
		forwarderCtx = context.Background()
	}
	for {
		if creds := f.getUserCredentials(ctx); creds != nil {
			return creds, nil
		}
		requestCtx, finish := f.getOrCreateRequestContext(ctx.key())
		if finish == nil {
			select {
			case <-requestCtx.Done():
				continue
			case <-forwarderCtx.Done():
				return nil, trace.BadParameter("forwarder is closing, aborting the request")
			}
		}

		// A previous request may have filled the cache between our first lookup
		// and our turn as the active requester.
		if creds := f.getUserCredentials(ctx); creds != nil {
			finish()
			return creds, nil
		}
		creds, err := f.requestCertificate(ctx)
		if err == nil {
			err = f.setUserCredentials(ctx, creds)
		}
		finish()
		return creds, trace.Wrap(err)
	}
}

func (f *Forwarder) setUserCredentials(ctx authContext, tlsConfig *tls.Config) error {
	if len(tlsConfig.Certificates) == 0 || len(tlsConfig.Certificates[0].Certificate) == 0 {
		return trace.BadParameter("Kubernetes client certificate is missing")
	}
	cert, err := x509.ParseCertificate(tlsConfig.Certificates[0].Certificate[0])
	if err != nil {
		return trace.Wrap(err)
	}
	now := f.now()
	if now.Add(time.Minute).After(cert.NotAfter) {
		return trace.BadParameter("Kubernetes client certificate expires in less than one minute")
	}

	ttl := cert.NotAfter.Sub(now.Add(time.Minute))
	if ctx.sessionTTL > 0 && ctx.sessionTTL < ttl {
		ttl = ctx.sessionTTL
	}
	// ttlmap has a one-second minimum. Retrieval checks NotAfter again so a
	// certificate near the one-minute boundary is never reused past it.
	if ttl < time.Second {
		ttl = time.Second
	}
	f.Lock()
	defer f.Unlock()
	if f.userCredentials == nil {
		cacheClock := f.Clock
		if cacheClock == nil {
			cacheClock = clockwork.NewRealClock()
		}
		f.userCredentials, err = ttlmap.New(defaults.ClientCacheSize, ttlmap.Clock(cacheClock))
		if err != nil {
			return trace.Wrap(err)
		}
	}
	return trace.Wrap(f.userCredentials.Set(ctx.key(), &userCredentials{tlsConfig: tlsConfig, notAfter: cert.NotAfter}, ttl))
}

